WITH lines AS (SELECT id, service, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, value) SELECT id, service, log_ts, level, latency_ms, key, value, AVG(latency_ms) OVER (ORDER BY latency_ms, id, key ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS latency_ms_avg_3_prior, AVG(latency_ms) OVER (PARTITION BY level ORDER BY latency_ms, id, key ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS latency_ms_avg_2_prior, RANK() OVER (PARTITION BY service ORDER BY latency_ms NULLS FIRST) AS latency_ms_rank FROM lines
